def transform(grid):
    # In each outlined 2-colored rectangle, recolor its interior background cells to 8.
    g=[r[:] for r in grid]
    R,C=len(g),len(g[0])
    seen=set()
    for r in range(R):
      for c in range(C):
        if g[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; comp=[]; seen.add((r,c))
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<R and 0<=xx<C and g[yy][xx]==2 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        # Components that form the complete boundary of a rectangle, fill their interior.
        r0=min(y for y,x in comp); r1=max(y for y,x in comp)
        c0=min(x for y,x in comp); c1=max(x for y,x in comp)
        boundary={(y,x) for y,x in comp if y in (r0,r1) or x in (c0,c1)}
        expected={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if y in (r0,r1) or x in (c0,c1)}
        if boundary==expected and r1-r0>=2 and c1-c0>=2:
          for y in range(r0+1,r1):
            for x in range(c0+1,c1):
              if g[y][x]==0: g[y][x]=8
    return g
